def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    winners_est = int(supply / WATER_REQ)
    if winners_est < 1:
        winners_est = 1

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 200:
            rich_opp += 1
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        bid = max(63.0, highest_prev + 1.5)
    elif hp <= 4 or no_water >= 1:
        if highest_prev >= 85:
            bid = 62.0
        else:
            bid = max(48.0, avg_prev + 3.0)
    else:
        if winners_est >= 2:
            bid = 26.0
            if highest_prev < 35:
                bid = 22.0
            elif highest_prev < 55:
                bid = 30.0
            elif highest_prev < 80:
                bid = 34.0
            else:
                bid = 28.0
        else:
            if highest_prev >= 85:
                bid = 58.0
            elif highest_prev >= 70:
                bid = 52.0
            else:
                bid = max(40.0, highest_prev + 2.0)

    if urgent_opp >= 2 and winners_est <= 1:
        bid += 6.0
    elif urgent_opp == 0 and winners_est >= 2 and hp >= 7:
        bid -= 4.0

    if rich_opp >= 2 and highest_prev >= 85 and hp > 4 and no_water == 0:
        bid -= 6.0

    if day >= 8:
        bid += 5.0
    if day >= 9 and hp <= 5:
        bid += 8.0

    max_safe = budget
    if hp > 5 and no_water == 0:
        reserve = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
        if max_safe > reserve:
            max_safe = max_safe
    bid = min(bid, max_safe)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = {k:v for k,v in opponents_status.items() if v['alive']}
    num_alive = len(alive_opps)

    prev_bids = []
    for opp in alive_opps.values():
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Base bid according to HP urgency
    if hp <= 2:
        base_bid = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 5:
        base_bid = min(budget, DAILY_SALARY * 0.6)
    else:
        base_bid = min(budget, DAILY_SALARY * 0.4)

    # Adjust based on yesterday's highest bid
    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev > DAILY_SALARY * 0.7:
            target = max_prev + 2.0
            if hp <= 2:
                target = max(target, DAILY_SALARY * 0.8)
            base_bid = min(budget, target)
        else:
            base_bid = min(budget, max(base_bid, max_prev + 1.0))

    # Adjust for number of alive opponents
    if num_alive >= 3:
        base_bid = min(budget, max(base_bid, DAILY_SALARY * 0.5))
    elif num_alive <= 1:
        base_bid = min(budget, base_bid * 0.7)

    final_bid = min(budget, max(1, base_bid))
    return round(final_bid, 2)
